CREATE TABLE "companies" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "slug" varchar UNIQUE NOT NULL,
  "domain" varchar UNIQUE,
  "logo" varchar,
  "address" text,
  "phone" varchar,
  "email" varchar NOT NULL,
  "website" varchar,
  "industry" varchar,
  "company_size" varchar,
  "timezone" varchar DEFAULT 'UTC',
  "subscription_id" integer,
  "is_active" boolean DEFAULT true,
  "trial_ends_at" timestamp,
  "onboarding_completed" boolean DEFAULT false,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar UNIQUE NOT NULL,
  "password" varchar NOT NULL,
  "first_name" varchar,
  "last_name" varchar,
  "phone_number" varchar,
  "profile_picture" varchar,
  "company_id" integer,
  "is_active" boolean DEFAULT true,
  "is_staff" boolean DEFAULT false,
  "is_superuser" boolean DEFAULT false,
  "is_platform_admin" boolean DEFAULT false,
  "is_company_owner" boolean DEFAULT false,
  "is_warehouse_manager" boolean DEFAULT false,
  "is_production_manager" boolean DEFAULT false,
  "is_logistics_coordinator" boolean DEFAULT false,
  "is_inventory_manager" boolean DEFAULT false,
  "is_driver" boolean DEFAULT false,
  "date_joined" timestamp DEFAULT (now()),
  "last_login" timestamp,
  "subscription_plan" varchar,
  "subscription_active" boolean DEFAULT false,
  "subscription_expires" timestamp
);

CREATE TABLE "company_invitations" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "email" varchar NOT NULL,
  "invited_by_id" integer NOT NULL,
  "role" varchar NOT NULL,
  "token" varchar UNIQUE NOT NULL,
  "accepted_at" timestamp,
  "expires_at" timestamp NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "platform_analytics" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer,
  "metric_name" varchar NOT NULL,
  "metric_value" decimal NOT NULL,
  "metric_date" date NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "audit_logs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer,
  "user_id" integer,
  "action" varchar NOT NULL,
  "resource" varchar NOT NULL,
  "resource_id" integer,
  "old_values" json,
  "new_values" json,
  "ip_address" varchar,
  "user_agent" text,
  "timestamp" timestamp DEFAULT (now())
);

CREATE TABLE "company_settings" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "setting_key" varchar NOT NULL,
  "setting_value" text,
  "setting_type" varchar NOT NULL,
  "is_encrypted" boolean DEFAULT false,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "categories" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "name" varchar NOT NULL,
  "description" text,
  "parent_id" integer,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "products" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "name" varchar NOT NULL,
  "sku" varchar NOT NULL,
  "description" text,
  "category_id" integer,
  "unit_price" decimal NOT NULL,
  "cost_price" decimal NOT NULL,
  "barcode" varchar,
  "weight" decimal,
  "dimensions" varchar,
  "is_active" boolean DEFAULT true,
  "image" varchar,
  "min_stock_level" integer DEFAULT 0,
  "max_stock_level" integer DEFAULT 0,
  "reorder_point" integer DEFAULT 0,
  "lead_time_days" integer DEFAULT 1,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "warehouses" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "name" varchar NOT NULL,
  "address" text NOT NULL,
  "manager_id" integer,
  "is_active" boolean DEFAULT true,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "inventory_items" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" integer NOT NULL,
  "warehouse_id" integer NOT NULL,
  "quantity" integer NOT NULL DEFAULT 0,
  "location" varchar,
  "last_checked" timestamp
);

CREATE TABLE "inventory_transactions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "inventory_item_id" integer NOT NULL,
  "transaction_type" varchar NOT NULL,
  "quantity" integer NOT NULL,
  "reference" varchar,
  "notes" text,
  "performed_by_id" integer,
  "timestamp" timestamp DEFAULT (now())
);

CREATE TABLE "production_orders" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "order_number" varchar NOT NULL,
  "product_id" integer NOT NULL,
  "quantity" integer NOT NULL,
  "status" varchar NOT NULL,
  "start_date" timestamp,
  "end_date" timestamp,
  "notes" text,
  "created_by_id" integer,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "production_steps" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "production_order_id" integer NOT NULL,
  "name" varchar NOT NULL,
  "description" text,
  "duration_hours" decimal,
  "status" varchar NOT NULL,
  "start_time" timestamp,
  "end_time" timestamp,
  "assigned_to_id" integer
);

CREATE TABLE "production_materials" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "production_order_id" integer NOT NULL,
  "product_id" integer NOT NULL,
  "quantity" integer NOT NULL,
  "warehouse_id" integer NOT NULL
);

CREATE TABLE "customer_orders" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "order_number" varchar NOT NULL,
  "customer_name" varchar NOT NULL,
  "customer_email" varchar NOT NULL,
  "customer_phone" varchar,
  "shipping_address" text NOT NULL,
  "billing_address" text,
  "status" varchar NOT NULL,
  "total_amount" decimal NOT NULL,
  "tax_amount" decimal DEFAULT 0,
  "shipping_amount" decimal DEFAULT 0,
  "discount_amount" decimal DEFAULT 0,
  "notes" text,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "order_items" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" integer NOT NULL,
  "product_id" integer NOT NULL,
  "quantity" integer NOT NULL,
  "unit_price" decimal NOT NULL,
  "total_price" decimal NOT NULL
);

CREATE TABLE "shipments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "shipment_number" varchar NOT NULL,
  "order_id" integer,
  "status" varchar NOT NULL,
  "carrier" varchar,
  "tracking_number" varchar,
  "shipping_date" timestamp,
  "estimated_delivery" timestamp,
  "actual_delivery" timestamp,
  "warehouse_id" integer NOT NULL,
  "driver_id" integer,
  "vehicle_info" varchar,
  "notes" text,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "shipment_items" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shipment_id" integer NOT NULL,
  "order_item_id" integer,
  "product_id" integer NOT NULL,
  "quantity" integer NOT NULL
);

CREATE TABLE "delivery_routes" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "route_name" varchar NOT NULL,
  "driver_id" integer,
  "vehicle_id" varchar,
  "start_time" timestamp,
  "end_time" timestamp,
  "status" varchar NOT NULL,
  "total_distance" decimal,
  "notes" text,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "route_stops" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "route_id" integer NOT NULL,
  "shipment_id" integer NOT NULL,
  "stop_number" integer NOT NULL,
  "address" text NOT NULL,
  "estimated_arrival" timestamp,
  "actual_arrival" timestamp,
  "departure_time" timestamp,
  "status" varchar NOT NULL,
  "notes" text
);

CREATE TABLE "warehouse_transfers" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "transfer_number" varchar NOT NULL,
  "source_warehouse_id" integer NOT NULL,
  "destination_warehouse_id" integer NOT NULL,
  "status" varchar NOT NULL,
  "initiated_by_id" integer,
  "approved_by_id" integer,
  "initiated_at" timestamp DEFAULT (now()),
  "completed_at" timestamp,
  "notes" text
);

CREATE TABLE "transfer_items" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "transfer_id" integer NOT NULL,
  "product_id" integer NOT NULL,
  "quantity" integer NOT NULL,
  "source_location" varchar,
  "destination_location" varchar
);

CREATE TABLE "subscription_plans" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "description" text,
  "price" decimal NOT NULL,
  "billing_cycle" varchar NOT NULL,
  "features" json,
  "is_active" boolean DEFAULT true,
  "stripe_price_id" varchar,
  "max_users" integer DEFAULT 1,
  "max_warehouses" integer DEFAULT 1,
  "max_products" integer DEFAULT 100,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "user_subscriptions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "plan_id" integer NOT NULL,
  "status" varchar NOT NULL,
  "payment_provider" varchar NOT NULL,
  "provider_subscription_id" varchar,
  "provider_customer_id" varchar,
  "start_date" timestamp NOT NULL,
  "end_date" timestamp NOT NULL,
  "trial_end" timestamp,
  "auto_renew" boolean DEFAULT true,
  "is_trial" boolean DEFAULT false,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "payment_transactions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "subscription_id" integer,
  "amount" decimal NOT NULL,
  "currency" varchar DEFAULT 'USD',
  "status" varchar NOT NULL,
  "payment_type" varchar NOT NULL,
  "provider" varchar NOT NULL,
  "provider_transaction_id" varchar,
  "provider_payment_method" varchar,
  "description" text,
  "receipt_url" varchar,
  "invoice_number" varchar,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE TABLE "payment_methods" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "type" varchar NOT NULL,
  "provider" varchar NOT NULL,
  "last_four" varchar,
  "expiry_month" varchar,
  "expiry_year" varchar,
  "card_brand" varchar,
  "phone_number" varchar,
  "wallet_address" varchar,
  "currency" varchar,
  "provider_payment_method_id" varchar,
  "is_default" boolean DEFAULT false,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp
);

CREATE UNIQUE INDEX ON "platform_analytics" ("company_id", "metric_name", "metric_date");

CREATE UNIQUE INDEX ON "company_settings" ("company_id", "setting_key");

CREATE UNIQUE INDEX ON "categories" ("company_id", "name");

CREATE UNIQUE INDEX ON "products" ("company_id", "sku");

CREATE UNIQUE INDEX ON "warehouses" ("company_id", "name");

CREATE UNIQUE INDEX ON "inventory_items" ("product_id", "warehouse_id");

CREATE UNIQUE INDEX ON "production_orders" ("company_id", "order_number");

CREATE UNIQUE INDEX ON "customer_orders" ("company_id", "order_number");

CREATE UNIQUE INDEX ON "shipments" ("company_id", "shipment_number");

CREATE UNIQUE INDEX ON "warehouse_transfers" ("company_id", "transfer_number");

